// packages/frontend/src/main.tsx
//
// React entry point. Pure plumbing: mount React, hand control to TanStack
// Router. There is no Markmate-specific logic here — every page lives in
// `src/routes/`, and `routeTree.gen.ts` is auto-generated by the router
// plugin during `vite dev`.
//
// You should not need to touch this file in Chapter 0.

import { StrictMode } from "react"
import ReactDOM from "react-dom/client"
import { RouterProvider, createRouter } from "@tanstack/react-router"
import { routeTree } from "./routeTree.gen"
import "./styles.css"

const router = createRouter({
  routeTree,
  defaultPreload: "intent",
})

declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router
  }
}

const rootEl = document.getElementById("root")
if (!rootEl) throw new Error("Root element #root not found")

ReactDOM.createRoot(rootEl).render(
  <StrictMode>
    <RouterProvider router={router} />
  </StrictMode>,
)
